'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var contains = require( '@stdlib/array/base/assert/contains' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var replace = require( '@stdlib/string/base/replace' );
var format = require( '@stdlib/string/format' );
var defaults = require( './defaults.js' );
var toJSON = require( './to_json.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getAlign = require( './align/get.js' );
var setAlign = require( './align/set.js' );

var getAnchor = require( './anchor/get.js' );
var setAnchor = require( './anchor/set.js' );

var getAngle = require( './angle/get.js' );
var setAngle = require( './angle/set.js' );

var getARIA = require( './aria/get.js' );
var setARIA = require( './aria/set.js' );

var getBaseline = require( './baseline/get.js' );
var setBaseline = require( './baseline/set.js' );

var getFont = require( './font/get.js' );
var setFont = require( './font/set.js' );
var getFontStyle = require( './font-style/get.js' );
var setFontStyle = require( './font-style/set.js' );

var getOrient = require( './orient/get.js' );
var setOrient = require( './orient/set.js' );

var getText = require( './text/get.js' );
var setText = require( './text/set.js' );


// FUNCTIONS //

/**
* Transforms an "assignment" error message to an "option validation" error message.
*
* @private
* @param {string} msg - error message
* @returns {string} transformed message
*/
function transformErrorMessage( msg ) {
	var m = replace( msg, /invalid assignment\. `([^ ]+)`/, 'invalid option. `$1` option' );
	return replace( m, /\. Value:/, '. Option:' );
}


// MAIN //

/**
* Title constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {boolean} [options.aria=true] - boolean indicating whether ARIA attributes should be included in SVG output
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {Title} title instance
*
* @example
* var title = new Title({
*     'text': 'Beep boop'
* });
* // returns <Title>
*/
function Title( options ) {
	var opts;
	var keys;
	var v;
	var k;
	var i;
	if ( !( this instanceof Title ) ) {
		return new Title( options );
	}
	EventEmitter.call( this );
	if ( !isPlainObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}
	// Resolve the default title configuration:
	opts = defaults();

	// Set internal title properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}
	// Resolve the list of provided options:
	keys = objectKeys( options );

	// Check for required properties...
	if ( !contains( keys, 'text' ) ) {
		throw new TypeError( 'invalid argument. Options argument must specify title text.' );
	}
	// Validate provided options by attempting to assign option values to corresponding title fields...
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		v = options[ k ];
		try {
			this[ k ] = v;
		} catch ( err ) {
			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
	}
	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( Title, EventEmitter );

/**
* Horizontal text alignment of the title and subtitle.
*
* @name align
* @memberof Title.prototype
* @type {(string|void)}
*
* @example
* var title = new Title({
*     'text': 'Beep boop',
*     'align': 'left'
* });
*
* var v = title.align;
* // returns 'left'
*/
setReadWriteAccessor( Title.prototype, 'align', getAlign, setAlign );

/**
* Anchor position for placing the title and subtitle.
*
* @name anchor
* @memberof Title.prototype
* @type {(string|void)}
* @default 'middle'
*
* @example
* var title = new Title({
*     'text': 'Beep boop',
*     'anchor': 'start'
* });
*
* var v = title.anchor;
* // returns 'start'
*/
setReadWriteAccessor( Title.prototype, 'anchor', getAnchor, setAnchor );

/**
* Angle (in degrees) of the title and subtitle text.
*
* @name angle
* @memberof Title.prototype
* @type {(number|void)}
*
* @example
* var title = new Title({
*     'text': 'Beep boop',
*     'angle': 90
* });
*
* var v = title.angle;
* // returns 90
*/
setReadWriteAccessor( Title.prototype, 'angle', getAngle, setAngle );

/**
* Vertical baseline of the title and subtitle text.
*
* @name baseline
* @memberof Title.prototype
* @type {(string|void)}
*
* @example
* var title = new Title({
*     'text': 'Beep boop',
*     'baseline': 'top'
* });
*
* var v = title.baseline;
* // returns 'top'
*/
setReadWriteAccessor( Title.prototype, 'baseline', getBaseline, setBaseline );

/**
* Boolean indicating whether ARIA attributes should be included in SVG output.
*
* @name aria
* @memberof Title.prototype
* @type {boolean}
* @default true
*
* @example
* var title = new Title({
*     'text': 'Beep boop',
*     'aria': false
* });
*
* var v = title.aria;
* // returns false
*/
setReadWriteAccessor( Title.prototype, 'aria', getARIA, setARIA );

/**
* Font name of the title text.
*
* @name font
* @memberof Title.prototype
* @type {(string|void)}
*
* @example
* var title = new Title({
*     'text': 'Beep boop',
*     'font': 'Arial'
* });
*
* var v = title.font;
* // returns 'Arial'
*/
setReadWriteAccessor( Title.prototype, 'font', getFont, setFont );

/**
* Font style of the title text.
*
* @name fontStyle
* @memberof Title.prototype
* @type {(string|void)}
*
* @example
* var title = new Title({
*     'text': 'Beep boop',
*     'fontStyle': 'Arial'
* });
*
* var v = title.fontStyle;
* // returns 'Arial'
*/
setReadWriteAccessor( Title.prototype, 'fontStyle', getFontStyle, setFontStyle );

/**
* Title orientation.
*
* @name orient
* @memberof Title.prototype
* @type {string}
*
* @example
* var title = new Title({
*     'text': 'Beep boop',
*     'orient': 'bottom'
* });
*
* var v = title.orient;
* // returns 'bottom'
*/
setReadWriteAccessor( Title.prototype, 'orient', getOrient, setOrient );

/**
* Title text.
*
* @name text
* @memberof Title.prototype
* @type {string}
*
* @example
* var title = new Title({
*     'text': 'Beep boop'
* });
*
* var v = title.text;
* // returns 'Beep boop'
*/
setReadWriteAccessor( Title.prototype, 'text', getText, setText );

/**
* Serializes a title to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof Title.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var title = new Title({
*     'text': 'Beep boop'
* });
*
* var v = title.toJSON();
* // returns {...}
*/
setReadOnly( Title.prototype, 'toJSON', toJSON );


// EXPORTS //

module.exports = Title;
